// Restore the conversational item after the rate-limit write.
// The HTTP write returns a rate_limit row, but Route by Deity needs deity/usermessage/source.
const state = $('Evaluate Rate Limit').first().json;
const updateResult = $input.first().json;

return {
  ...state,
  rateLimitUpdateOk: !updateResult?.error,
  rateLimitUpdateResult: updateResult
};

// Normalize and validate web payload before the shared context contract.
const body = $input.first().json.body || $input.first().json;
const allowedLanguages = new Set(['es', 'en']);
const allowedDeities = new Set(['jewish', 'christian', 'buddhist', 'olympus', 'future_self']);

const message = String(body.message || '').trim();
const language = allowedLanguages.has(body.language) ? body.language : 'es';
const deity = body.deity || 'jewish';
const sessionId = String(body.sessionId || '').trim();
const ipHash = String(body.ipHash || '').trim();
const username = String(body.username || sessionId || 'web_user').substring(0, 48);

if (!message) {
  throw new Error('Web request requires a non-empty message');
}
if (!allowedDeities.has(deity)) {
  throw new Error(`Unsupported web deity: ${deity}`);
}
if (!sessionId || !ipHash) {
  throw new Error('Web request requires sessionId and ipHash for identity and rate limits');
}

function hashString(str) {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    hash = ((hash << 5) - hash) + str.charCodeAt(i);
    hash |= 0;
  }
  return Math.abs(hash);
}

const webUserId = hashString(`${ipHash}:${sessionId}`);

return {
  chatId: webUserId,
  username: `web_${username}`,
  usermessage: message,
  language,
  deity,
  selectedLanguage: null,
  selectedDeity: null,
  hasState: true,
  eventType: 'process_message',
  callbackData: null,
  messageId: 0,
  source: 'web',
  ipHash,
  sessionId,
  webUserId
};

// Web Rate Limit Evaluator - runs before LLM/API work.
const state = $('Normalize Context').first().json;
const ipHash = state.ipHash;
const language = state.language || 'es';
let rateLimitState = $input.first().json;

function extract(data) {
  if (!data) return null;
  if (Array.isArray(data)) return data.length > 0 ? extract(data[0]) : null;
  if (data.json && typeof data.json === 'object') return extract(data.json);
  if (data.ip_hash !== undefined) return data;
  return null;
}

const rl = extract(rateLimitState);
const now = new Date();
const WINDOW_MS = 24 * 60 * 60 * 1000;
const MAX_REQUESTS = 3;
let count = 0;
let windowStart = now;
let blocked = false;
let timeRemaining = null;

if (rl) {
  count = rl.count || 0;
  windowStart = new Date(rl.window_start || now.toISOString());
  const elapsed = now - windowStart;
  if (elapsed >= WINDOW_MS) {
    count = 0;
    windowStart = now;
  } else if (count >= MAX_REQUESTS) {
    blocked = true;
    const msLeft = WINDOW_MS - elapsed;
    timeRemaining = {
      hours: Math.floor(msLeft / (60 * 60 * 1000)),
      minutes: Math.floor((msLeft % (60 * 60 * 1000)) / (60 * 1000)),
      totalMs: msLeft
    };
  }
}

const newCount = blocked ? count : count + 1;
const blockedMessage = blocked
  ? (language === 'es'
      ? `🕊️ Has consultado ${MAX_REQUESTS} veces en las últimas 24 horas.\n\nPodés volver en ${timeRemaining.hours}h ${timeRemaining.minutes}min.`
      : `🕊️ You have consulted ${MAX_REQUESTS} times in the last 24 hours.\n\nYou can return in ${timeRemaining.hours}h ${timeRemaining.minutes}min.`)
  : '';

return {
  ...state,
  rateLimit: {
    blocked,
    count: newCount,
    windowStart: windowStart.toISOString(),
    timeRemaining
  },
  blockedMessage
};

// Build JSON response for rate-limited user
const data = $input.first().json;
return {
  ok: false,
  blocked: true,
  message: data.blockedMessage,
  timeRemaining: data.rateLimit.timeRemaining,
  language: data.language
};

// Build JSON response for successful deity reply
// Receives merged data from one of the Assemble nodes (whichever fired)
const data = $input.first().json;

return {
  ok: true,
  blocked: false,
  response: data.output || '',
  citation: data.citation || '',
  deity: data.tradition || 'jewish',
  language: data.language || 'es',
  source: 'web'
};

// Map user message to Bible reference using query decomposition.
const data = $input.first().json;
const userMessage = data.usermessage || '';
const language = data.language || 'es';
const decomposition = data.decomposition || { topics: [], subQueries: [userMessage] };
const topics = decomposition.topics || [];

const topicMap = {
  love: 'john+15:9-12', amor: 'john+15:9-12',
  forgiveness: 'matthew+6:14-15', 'perdón': 'matthew+6:14-15', perdon: 'matthew+6:14-15',
  faith: 'hebrews+11:1', fe: 'hebrews+11:1', hope: 'romans+15:13', esperanza: 'romans+15:13',
  peace: 'philippians+4:6-7', paz: 'philippians+4:6-7', suffering: 'romans+8:18', sufrimiento: 'romans+8:18', dolor: 'romans+8:18',
  death: 'john+11:25', muerte: 'john+11:25', life: 'john+10:10', vida: 'john+10:10',
  prayer: 'matthew+6:9-13', 'oración': 'matthew+6:9-13', oracion: 'matthew+6:9-13',
  wisdom: 'james+1:5', 'sabiduría': 'james+1:5', sabiduria: 'james+1:5',
  salvation: 'ephesians+2:8-9', 'salvación': 'ephesians+2:8-9', salvacion: 'ephesians+2:8-9',
  god: 'psalm+23', dios: 'psalm+23', purpose: 'jeremiah+29:11', 'propósito': 'jeremiah+29:11', proposito: 'jeremiah+29:11'
};

let reference = '';
for (const topic of topics) {
  const lower = String(topic).toLowerCase();
  for (const [key, ref] of Object.entries(topicMap)) {
    if (lower.includes(key) || key.includes(lower)) {
      reference = ref;
      break;
    }
  }
  if (reference) break;
}
if (!reference) {
  const lower = userMessage.toLowerCase();
  for (const [topic, ref] of Object.entries(topicMap)) {
    if (lower.includes(topic)) {
      reference = ref;
      break;
    }
  }
}
if (!reference) reference = 'psalm+23';

return {
  ...data,
  bibleReference: reference,
  usermessage: userMessage,
  language,
  decompositionUsed: topics.length > 0
};

// Merge State - combine parsed Telegram event with persisted Supabase state
const parsed = $('Parse Input').first().json;
const rawState = $input.first().json;

if (rawState?.error) {
  const message = rawState.error.message || JSON.stringify(rawState.error);
  throw new Error(`Get User State failed before routing: ${message}`);
}

function extractState(data) {
  if (!data) return null;
  if (Array.isArray(data)) return data.map(extractState).find(Boolean) || null;
  if (data.json && typeof data.json === 'object') return extractState(data.json);
  if (data.body && typeof data.body === 'object') return extractState(data.body);
  if (data.data && typeof data.data === 'object') return extractState(data.data);
  if (data.chat_id !== undefined || data.chatId !== undefined) return data;
  return null;
}

const state = extractState(rawState);
const savedLanguage = state?.language || null;
const savedDeity = state?.deity || null;

let eventType = parsed.eventType;

if (eventType === 'process_message') {
  if (!savedLanguage) {
    eventType = 'show_language_picker';
  } else if (!savedDeity) {
    eventType = 'show_deity_picker';
  }
}

const language = parsed.selectedLanguage || savedLanguage || 'es';
const deity = parsed.selectedDeity || savedDeity || null;

return {
  eventType,
  chatId: parsed.chatId,
  username: parsed.username,
  source: parsed.source,
  selectedLanguage: parsed.selectedLanguage,
  selectedDeity: parsed.selectedDeity,
  language,
  deity,
  usermessage: parsed.usermessage,
  callbackId: parsed.callbackId,
  callbackData: parsed.callbackData,
  messageId: parsed.messageId,
  hasState: !!state,
  savedLanguage,
  savedDeity
};

// Canonical context for all downstream routing.
const input = $input.first().json;

const allowedEvents = new Set([
  'show_language_picker',
  'save_language',
  'show_deity_picker',
  'save_deity',
  'forget',
  'process_message'
]);
const allowedDeities = new Set(['jewish', 'christian', 'buddhist', 'olympus', 'future_self']);
const allowedLanguages = new Set(['es', 'en']);

const source = input.source === 'web' ? 'web' : 'telegram';
const channel = source;
const eventType = input.eventType || '';
const language = allowedLanguages.has(input.language) ? input.language : 'es';
const deity = input.deity || input.selectedDeity || null;
const chatId = input.chatId ?? input.webUserId;
const usermessage = String(input.usermessage || '').trim();

if (!allowedEvents.has(eventType)) {
  throw new Error(`Unsupported eventType: ${eventType || '(empty)'}`);
}
if (!chatId) {
  throw new Error('Missing chatId/webUserId in canonical context');
}
if (eventType === 'process_message' && !usermessage) {
  throw new Error('process_message requires a non-empty usermessage');
}
if (eventType === 'process_message' && !allowedDeities.has(deity)) {
  throw new Error(`process_message requires a valid deity, got: ${deity || '(empty)'}`);
}
if (input.selectedDeity && !allowedDeities.has(input.selectedDeity)) {
  throw new Error(`Unsupported selectedDeity: ${input.selectedDeity}`);
}

const sessionId = input.sessionId || (source === 'telegram' ? String(chatId) : null);
const ipHash = input.ipHash || null;
const userKey = source === 'web'
  ? `web:${ipHash || 'missing-ip'}:${sessionId || 'missing-session'}`
  : `telegram:${chatId}`;
const rateLimitKey = source === 'web' ? (ipHash || userKey) : String(chatId);

return {
  ...input,
  source,
  channel,
  eventType,
  chatId,
  userKey,
  username: input.username || 'unknown',
  language,
  deity,
  selectedLanguage: input.selectedLanguage || null,
  selectedDeity: input.selectedDeity || null,
  usermessage,
  callbackData: input.callbackData || null,
  callbackId: input.callbackId || null,
  messageId: input.messageId || null,
  sessionId,
  ipHash,
  rateLimitKey,
  hasState: !!input.hasState,
  decomposition: input.decomposition || null,
  retrievalContext: input.retrievalContext || '',
  citation: input.citation || '',
  output: input.output || ''
};

// Build welcome message after deity selection (now supports 5 deities)
// Use Merge State for the current execution data
const state = $('Merge State').first().json;
const language = state.language || 'es';
const deity = state.selectedDeity || state.deity;

const disclaimers = {
  es: "🕊️ Soy una representación espiritual generada con inteligencia artificial. Mis palabras son una invitación a la reflexión, no una verdad absoluta. Las conversaciones se guardan de forma anónima para fines experimentales. Escribe /forget para borrar tu historial.",
  en: "🕊️ I am a spiritual representation generated with artificial intelligence. My words are an invitation to reflection, not absolute truth. Conversations are stored anonymously to experimental purposes. Type /forget to erase your history."
};

const welcomes = {
  jewish: {
    es: "Shalom! Soy la representacion de H'shem. Te escucho desde la tradición judía. ¿Qué hay en tu corazón hoy?",
    en: "Shalom! I'm H'shem, The Eternal. I listen to you from the Jewish tradition. What is in your heart today?"
  },
  christian: {
    es: "Hijo mío, soy Dios Padre, hablándote desde la tradición cristiana. Te escucho. ¿Qué quieres decirme?",
    en: "My child, I am God the Father, speaking to you from the Christian tradition. I am listening. What do you wish to tell Me?"
  },
  buddhist: {
    es: "Soy el Buda Shakyamuni. Siéntate, respira, y cuéntame qué te trae aquí.",
    en: "I am the Buddha Shakyamuni. Sit, breathe, and tell me what brings you here."
  },
  olympus: {
    es: "Mortal, has invocado al Olimpo. Somos los doce dioses. Habla, y aquel de nosotros que sea pertinente responderá.",
    en: "Mortal, you have summoned Olympus. We are the twelve Olympian gods. Speak, and whichever of us is pertinent shall respond."
  },
  future_self: {
    es: "Hola. Soy tu, hablándote desde diez años en el futuro. Reconozco esta pregunta porque también la hice. Cuentame que quieres saber.",
    en: "Hello. I am you, speaking from ten years in the future. I recognize this question because I asked it too. Tell me what do you need to know."
  }
};

const fallback = welcomes.jewish;
const welcomeText = (welcomes[deity] && welcomes[deity][language]) || fallback[language];
const fullText = `${disclaimers[language]}\n\n${welcomeText}`;

return {
  chatId: state.chatId,
  text: fullText,
  language: language,
  deity: deity,
  username: state.username
};

// Assemble Jewish response after RAG-grounded agent.
const data = $input.first().json;
const state = $('Format Citation').first().json;
const language = state.language || 'es';
const citation = state.citation || '';
const errorMsg = language === 'es'
  ? "Lo siento, no pude generar una respuesta en este momento."
  : "I'm sorry, I couldn't generate a response at this moment.";

let finalMessage = data.output || errorMsg;
if (citation) finalMessage += `\n\n---\n${citation}`;

return {
  ...state,
  output: finalMessage,
  tradition: 'jewish',
  citation
};

// Build LangFuse trace payload
// This runs after Log Conversation; sends trace asynchronously to LangFuse Cloud
const data = $input.first().json;

// Pick up the assembled response data from previous nodes
// Use a try-catch fallback since this depends on the deity branch
let response, usermessage, deity, language, chatId, username, citation;

try {
  // Try to find data from any of the assemble response nodes
  const assembleSources = [
    'Assemble Response',
    'Assemble Christian Response', 
    'Assemble Buddhist Response',
    'Assemble Olympus Response',
    'Assemble Future Self Response'
  ];

  let assembled = null;
  for (const src of assembleSources) {
    try {
      const node = $(src);
      if (node && node.first()) {
        assembled = node.first().json;
        break;
      }
    } catch (e) { continue; }
  }

  if (assembled) {
    response = assembled.output || '';
    usermessage = assembled.usermessage || '';
    deity = assembled.tradition || 'unknown';
    language = assembled.language || 'es';
    chatId = assembled.chatId || 0;
    username = assembled.username || 'anonymous';
    citation = assembled.citation || '';
  } else {
    response = data.output || '';
    usermessage = data.usermessage || '';
    deity = data.tradition || 'unknown';
    language = data.language || 'es';
    chatId = data.chatId || 0;
    username = 'anonymous';
    citation = '';
  }
} catch (e) {
  response = '';
  usermessage = '';
  deity = 'unknown';
  language = 'es';
  chatId = 0;
  username = 'anonymous';
  citation = '';
}

const now = new Date().toISOString();
const traceId = `${chatId}_${Date.now()}`;

// Build LangFuse ingestion payload
const payload = {
  batch: [
    {
      id: traceId,
      type: 'trace-create',
      timestamp: now,
      body: {
        id: traceId,
        timestamp: now,
        name: `god_is_typing_${deity}`,
        userId: String(chatId),
        sessionId: `${chatId}_${deity}`,
        input: usermessage,
        output: response,
        metadata: {
          deity: deity,
          language: language,
          hasCitation: citation.length > 0,
          source: 'telegram'
        },
        tags: [deity, language, 'production']
      }
    }
  ]
};

return { langfusePayload: payload, traceId: traceId };

// Restore assembled response after Log Conversation replaces the current item.
const assembleSources = [
  'Assemble Response',
  'Assemble Christian Response',
  'Assemble Buddhist Response',
  'Assemble Olympus Response',
  'Assemble Future Self Response'
];

for (const src of assembleSources) {
  try {
    const item = $(src).first().json;
    if (item && item.output) return item;
  } catch (e) {}
}

return $input.first().json;

// Map user message to Sefaria-friendly search keywords using query decomposition.
const data = $input.first().json;
const userMessage = data.usermessage || '';
const language = data.language || 'es';
const decomposition = data.decomposition || { topics: [], subQueries: [userMessage] };
const topics = decomposition.topics || [];

const topicMap = {
  forgiveness: 'forgiveness selichah', 'perdón': 'forgiveness selichah', perdon: 'forgiveness selichah',
  charity: 'tzedakah charity', caridad: 'tzedakah charity', tzedaka: 'tzedakah charity',
  love: 'love ahavah', amor: 'love ahavah', creation: 'creation bereshit', 'creación': 'creation bereshit', creacion: 'creation bereshit',
  shabbat: 'shabbat', shabat: 'shabbat', torah: 'torah', 'torá': 'torah', tora: 'torah',
  prayer: 'prayer tefillah', 'oración': 'prayer tefillah', oracion: 'prayer tefillah', rezo: 'prayer tefillah',
  justice: 'justice tzedek', justicia: 'justice tzedek', covenant: 'covenant brit', pacto: 'covenant brit', alianza: 'covenant brit',
  faith: 'faith emunah', fe: 'faith emunah', peace: 'peace shalom', paz: 'peace shalom',
  sin: 'sin chet', pecado: 'sin chet', repentance: 'repentance teshuvah', arrepentimiento: 'repentance teshuvah',
  god: 'god hashem', dios: 'god hashem', hashem: 'god hashem', suffering: 'suffering yissurim', sufrimiento: 'suffering yissurim',
  death: 'death mavet', muerte: 'death mavet', life: 'life chayim', vida: 'life chayim', soul: 'soul neshamah', alma: 'soul neshamah'
};

let query = '';
for (const topic of topics) {
  const lowerTopic = String(topic).toLowerCase();
  for (const [key, keywords] of Object.entries(topicMap)) {
    if (lowerTopic.includes(key) || key.includes(lowerTopic)) {
      query = keywords;
      break;
    }
  }
  if (query) break;
}
if (!query) {
  const lowerMsg = userMessage.toLowerCase();
  for (const [topic, keywords] of Object.entries(topicMap)) {
    if (lowerMsg.includes(topic)) {
      query = keywords;
      break;
    }
  }
}
if (!query) {
  const words = userMessage.replace(/[?¿.,!¡]/g, '').split(/\s+/).filter(w => w.length > 4);
  query = words.slice(0, 3).join(' ') || 'wisdom';
}

return {
  ...data,
  sefariaQuery: query,
  usermessage: userMessage,
  language,
  decompositionUsed: topics.length > 0
};

// Extract Sefaria context before the Jewish agent runs.
const data = $input.first().json;
const state = $('Sefaria Keywords').first().json;
const language = state.language || 'es';
let citation = '';
let retrievalContext = '';

try {
  const hits = data.body?.hits?.hits || data.hits?.hits || [];
  if (hits.length > 0) {
    const hit = hits[0]._source || hits[0];
    const ref = hit.ref || (language === 'es' ? 'Texto judío' : 'Jewish text');
    const text = String(hit.translation || hit.text || '').replace(/\s+/g, ' ').trim();
    if (text) {
      const truncated = text.length > 600 ? `${text.substring(0, 597)}...` : text;
      citation = `📜 ${ref}: "${truncated.length > 280 ? truncated.substring(0, 277) + '...' : truncated}"`;
      retrievalContext = `${ref}: ${truncated}`;
    }
  }
} catch (e) {
  retrievalContext = '';
}

return {
  ...state,
  citation,
  retrievalContext
};

// Assemble Christian response after Bible-grounded agent.
const data = $input.first().json;
const state = $('Format Bible Citation').first().json;
const language = state.language || 'es';
const citation = state.citation || '';
const errorMsg = language === 'es'
  ? "Lo siento, no pude generar una respuesta en este momento."
  : "I'm sorry, I couldn't generate a response at this moment.";

let finalMessage = data.output || errorMsg;
if (citation) finalMessage += `\n\n---\n${citation}`;

return {
  ...state,
  output: finalMessage,
  tradition: 'christian',
  citation
};

// Buddhist has no RAG citation, just LLM output.
const data = $input.first().json;
const state = $('Route by Deity').first().json;
const language = state.language || 'es';
const errorMsg = language === 'es'
  ? "Lo siento, no pude generar una respuesta en este momento."
  : "I'm sorry, I couldn't generate a response at this moment.";

return {
  ...state,
  output: data.output || errorMsg,
  tradition: 'buddhist',
  citation: ''
};

// Olympus has no RAG citation, just LLM output.
const data = $input.first().json;
const state = $('Route by Deity').first().json;
const language = state.language || 'es';
const errorMsg = language === 'es'
  ? "Los Olímpicos guardan silencio en este momento."
  : "The Olympians keep silence at this moment.";

return {
  ...state,
  output: data.output || errorMsg,
  tradition: 'olympus',
  citation: ''
};

// Future Self has no RAG citation, just LLM output.
const data = $input.first().json;
const state = $('Route by Deity').first().json;
const language = state.language || 'es';
const errorMsg = language === 'es'
  ? "No tengo nada que decirte en este momento. Volvé en un rato."
  : "I have nothing to tell you right now. Come back in a while.";

return {
  ...state,
  output: data.output || errorMsg,
  tradition: 'future_self',
  citation: ''
};

// Format Bible API response before the Christian agent runs.
const data = $input.first().json;
const state = $('Bible Keywords1').first().json;
let citation = '';
let retrievalContext = '';

try {
  if (data.reference && data.text) {
    const ref = data.reference;
    const text = String(data.text).trim().replace(/\s+/g, ' ');
    const contextText = text.length > 600 ? `${text.substring(0, 597)}...` : text;
    citation = `📖 ${ref}: "${contextText.length > 280 ? contextText.substring(0, 277) + '...' : contextText}"`;
    retrievalContext = `${ref}: ${contextText}`;
  }
} catch (e) {
  retrievalContext = '';
}

return {
  ...state,
  citation,
  retrievalContext
};

// Restore the web message item after the rate-limit write.
// Route by Deity needs the original normalized payload, not the web_rate_limit row.
const state = $('Evaluate Web Rate Limit').first().json;
const updateResult = $input.first().json;

return {
  ...state,
  rateLimitUpdateOk: !updateResult?.error,
  rateLimitUpdateResult: updateResult
};

// Non-RAG deities do not need an LLM decomposition step.
const state = $input.first().json;
const decomposition = {
  intent: state.usermessage,
  subQueries: [state.usermessage],
  topics: [],
  isExistential: true,
  skipped: true
};

return {
  ...state,
  decomposition,
  bestQuery: state.usermessage,
  enrichedContext: `Intent: ${state.usermessage}\nKey topics: none\nSub-queries explored: ${state.usermessage}`
};

// Parse the JSON output from Query Decomposer and merge with canonical state.
const decompOutput = $input.first().json.output || '{}';
function stateFrom(nodeName) {
  try {
    const item = $(nodeName).first();
    return item ? item.json : null;
  } catch {
    return null;
  }
}

// Estado canónico: viene de Restore * (después del rate limit), no del Switch.
const state =
  stateFrom('Restore Web Message State') ||
  stateFrom('Restore Telegram Message State') ||
  stateFrom('Normalize Context');

if (!state) {
  throw new Error('No hay estado. Web: Restore Web Message State. Telegram: Restore Telegram Message State.');
}

let decomposition = {
  intent: state.usermessage,
  subQueries: [state.usermessage],
  topics: [],
  isExistential: true
};

try {
  let jsonText = decompOutput;
  const jsonMatch = decompOutput.match(/```(?:json)?\s*(\{[\s\S]*?\})\s*```/);
  if (jsonMatch) {
    jsonText = jsonMatch[1];
  } else {
    const firstBrace = decompOutput.indexOf('{');
    const lastBrace = decompOutput.lastIndexOf('}');
    if (firstBrace >= 0 && lastBrace > firstBrace) {
      jsonText = decompOutput.substring(firstBrace, lastBrace + 1);
    }
  }
  const parsed = JSON.parse(jsonText);
  decomposition = {
    intent: parsed.intent || state.usermessage,
    subQueries: Array.isArray(parsed.subQueries) && parsed.subQueries.length > 0 ? parsed.subQueries.slice(0, 3) : [state.usermessage],
    topics: Array.isArray(parsed.topics) ? parsed.topics.slice(0, 4) : [],
    isExistential: parsed.isExistential !== undefined ? parsed.isExistential : true
  };
} catch (e) {
  decomposition.parseError = e.message;
}

return {
  ...state,
  decomposition,
  bestQuery: decomposition.subQueries[0],
  enrichedContext: `Intent: ${decomposition.intent}\nKey topics: ${decomposition.topics.join(', ') || 'none'}\nSub-queries explored: ${decomposition.subQueries.join('; ')}`
};

// Telegram Rate Limit Evaluator - runs before LLM/API work.
const canonicalState = $('Normalize Context').first().json;
const language = canonicalState.language || 'es';
let rateLimitState = $input.first().json;

function extract(data) {
  if (!data) return null;
  if (Array.isArray(data)) return data.length > 0 ? extract(data[0]) : null;
  if (data.json && typeof data.json === 'object') return extract(data.json);
  if (data.chat_id !== undefined && data.chat_id !== null) return data;
  return null;
}

const state = extract(rateLimitState);
const now = new Date();
const WINDOW_MS = 24 * 60 * 60 * 1000;
const MAX_REQUESTS = 3;
let count = 0;
let windowStart = now;
let blocked = false;
let timeRemaining = null;
let isNewWindow = false;

if (state) {
  count = state.count || 0;
  windowStart = new Date(state.window_start || now.toISOString());
  const elapsed = now - windowStart;
  if (elapsed >= WINDOW_MS) {
    count = 0;
    windowStart = now;
    isNewWindow = true;
  } else if (count >= MAX_REQUESTS) {
    blocked = true;
    const msLeft = WINDOW_MS - elapsed;
    timeRemaining = {
      hours: Math.floor(msLeft / (60 * 60 * 1000)),
      minutes: Math.floor((msLeft % (60 * 60 * 1000)) / (60 * 1000)),
      totalMs: msLeft
    };
  }
} else {
  isNewWindow = true;
}

const newCount = blocked ? count : count + 1;
const blockedMessage = blocked
  ? (language === 'es'
      ? `🕊️${MAX_REQUESTS} veces en las últimas 24 horas es suficiente, mi pequeñ@ curios@.\n\nPuedes volver en ${timeRemaining.hours}h ${timeRemaining.minutes}min.`
      : `🕊️${MAX_REQUESTS} times in the last 24 hours, is enough my little curious girl/boy.\n\nYou can return in ${timeRemaining.hours}h ${timeRemaining.minutes}min.`)
  : '';

return {
  ...canonicalState,
  rateLimit: {
    blocked,
    count: newCount,
    windowStart: windowStart.toISOString(),
    isNewWindow,
    timeRemaining
  },
  blockedMessage
};

// Parse Input - normalize Telegram events for deterministic routing
const input = $input.first().json;
const message = input.message;
const callback = input.callback_query;

const chat = message?.chat || callback?.message?.chat || null;
const from = message?.from || callback?.from || {};
const chatId = chat?.id;
const username = from.username || chat?.username || from.first_name || 'unknown';

if (!chatId) {
  throw new Error(`Telegram event without chat id: ${JSON.stringify(input)}`);
}

let eventType = '';
let selectedLanguage = null;
let selectedDeity = null;
let usermessage = '';
const callbackId = callback?.id || null;
const callbackData = callback?.data || null;
const messageId = message?.message_id || callback?.message?.message_id || null;

const deityByCallback = {
  'deity:jewish': 'jewish',
  'deity:christian': 'christian',
  'deity:buddhist': 'buddhist',
  'deity:olympus': 'olympus',
  'deity:future_self': 'future_self'
};

if (callback) {
  const data = String(callback.data || '');

  if (data === 'lang:es' || data === 'lang:en') {
    eventType = 'save_language';
    selectedLanguage = data.split(':')[1];
  } else if (deityByCallback[data]) {
    eventType = 'save_deity';
    selectedDeity = deityByCallback[data];
  } else {
    throw new Error(`Unsupported callback data: ${data}`);
  }
} else if (message?.text) {
  const text = message.text.trim();

  if (text === '/start') {
    eventType = 'show_language_picker';
  } else if (text === '/forget') {
    eventType = 'forget';
  } else {
    eventType = 'process_message';
    usermessage = text;
  }
} else {
  throw new Error(`Unsupported Telegram event shape: ${JSON.stringify(input)}`);
}

return {
  chatId,
  username,
  eventType,
  selectedLanguage,
  selectedDeity,
  usermessage,
  source: 'telegram',
  callbackId,
  callbackData,
  messageId
};
